public class Thermostat {
    private int temp;
    public Thermostat() { temp = 68; }
    public void adjust(int delta) {
        if (temp + delta >= 60 && temp + delta <= 80) {
            temp += delta;
        }
    }
    public int getTemp() { return temp; }
}
```

